// Shaft Precision shaft (h6) (pins and rods). Generated by the standard parts library; threads are not modelled.
let TABLE = [
    [3.0],
    [4.0],
    [5.0],
    [6.0],
    [8.0],
    [10.0],
    [12.0],
    [16.0],
    [20.0],
    [25.0]
];
let row = [];
for r in TABLE { if abs(r[0] - size) < 1e-6 { row = r; } }
if row.len() == 0 { throw "no size " + size + "; the sizes are Ø3, Ø4, Ø5, Ø6, Ø8, Ø10, Ø12, Ø16, Ø20, Ø25"; }
if length <= 0.0 { throw "the length must be positive"; }

fn hex(s) {
    let r = s / sqrt(3.0);
    let p = [];
    for i in 0..6 { let a = (30.0 + 60.0 * i).to_radians(); p.push([r * cos(a), r * sin(a)]); }
    p
}
fn hexc(s, h, top, bottom) {
    let r0 = 0.475 * s;
    let big = 1.02 * s / sqrt(3.0);
    let dz = (big - r0) * 0.57735;
    let p = [[0.0, 0.0]];
    if bottom { p.push([r0, 0.0]); p.push([big, dz]); } else { p.push([big, 0.0]); }
    if top { p.push([big, h - dz]); p.push([r0, h]); } else { p.push([big, h]); }
    p.push([0.0, h]);
    prism(hex(s), h) & revolve(p, 360.0)
}
fn rp(x0, y0, x1, y1, h) { prism([[x0, y0], [x1, y0], [x1, y1], [x0, y1]], h) }

let r = size / 2; let c = 0.5;
revolve([[0.0, 0.0], [r - c, 0.0], [r, c], [r, length - c], [r - c, length], [0.0, length]], 360.0)

// NEMA Stepper motor (motors). Generated by the standard parts library; threads are not modelled.
let TABLE = [
    [8.0, 20.3, 16.0, 2.0, 2.5, 16.0, 1.5, 4.0, 10.0, 2.0],
    [11.0, 28.2, 23.0, 2.5, 3.0, 22.0, 2.0, 5.0, 20.0, 2.5],
    [14.0, 35.2, 26.0, 3.0, 3.5, 22.0, 2.0, 5.0, 20.0, 3.5],
    [17.0, 42.3, 31.0, 3.0, 4.5, 22.0, 2.0, 5.0, 24.0, 4.0],
    [23.0, 56.4, 47.14, 5.1, 6.0, 38.1, 1.6, 6.35, 21.0, 5.0]
];
let row = [];
for r in TABLE { if abs(r[0] - size) < 1e-6 { row = r; } }
if row.len() == 0 { throw "no size " + size + "; the sizes are NEMA 8, NEMA 11, NEMA 14, NEMA 17, NEMA 23"; }
if length <= 0.0 { throw "the length must be positive"; }

