    let big = 1.02 * s / sqrt(3.0);
    let dz = (big - r0) * 0.57735;
    let p = [[0.0, 0.0]];
    if bottom { p.push([r0, 0.0]); p.push([big, dz]); } else { p.push([big, 0.0]); }
    if top { p.push([big, h - dz]); p.push([r0, h]); } else { p.push([big, h]); }
    p.push([0.0, h]);
